 $("#f-ar").value=p.name_ar||"";$("#f-en").value=p.name_en||"";$("#f-ct").value=p.category_id||"";$("#f-br").value=p.brand||"";$("#f-bc").value=p.barcode||"";$("#f-pr").value=p.price==null?"":p.price;$("#f-op").value=p.old_price==null?"":p.old_price;$("#f-st").value=p.stock==null?0:p.stock;$("#f-cd").value=p.condition||"new";$("#f-wr").value=p.warranty||"";$("#f-da").value=p.desc_ar||"";$("#f-de").value=p.desc_en||"";$("#f-ac").value=p.active===false?"0":"1";$("#f-ft").value=p.featured?"1":"0";$("#f-sl").value=p.slug||"";
 var pvCost=null;
