 pvDraw();
 function drawI(){if(typeof pvDraw==="function")setTimeout(pvDraw,0);$("#f-ph").innerHTML=imgs.map(function(u,i){return '<div class="pi"><img src="'+esc(u)+'" alt=""><button class="dg sm" data-d="'+i+'" type="button">✕</button></div>'}).join("");[].forEach.call($("#f-ph").querySelectorAll("[data-d]"),function(b){b.onclick=function(){imgs.splice(+b.dataset.d,1);drawI()}})}
