/* EAN-13 (weight label) */
var EANL=["0001101","0011001","0010011","0111101","0100011","0110001","0101111","0111011","0110111","0001011"],EANG=["0100111","0110011","0011011","0100001","0011101","0111001","0000101","0010001","0001001","0010111"],EANR=["1110010","1100110","1101100","1000010","1011100","1001110","1010000","1000100","1001000","1110100"],EANP=["LLLLLL","LLGLGG","LLGGLG","LLGGGL","LGLLGG","LGGLLG","LGGGLL","LGLGLG","LGLGGL","LGGLGL"];
function eanChk(d12){var s=0,i;for(i=0;i<12;i++)s+=Number(d12[i])*(i%2?3:1);return String((10-s%10)%10)}
function eanBits(c){var p=EANP[Number(c[0])],b="101",i;for(i=1;i<7;i++)b+=(p[i-1]==="L"?EANL:EANG)[Number(c[i])];b+="01010";for(i=7;i<13;i++)b+=EANR[Number(c[i])];return b+"101"}
function eanSvg(c,h){var b=eanBits(c),r="",i;for(i=0;i<b.length;i++)if(b[i]==="1"){var j=i;while(j<b.length&&b[j]==="1")j++;r+='<rect x="'+i+'" y="0" width="'+(j-i)+'" height="'+h+'"/>';i=j-1}return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 95 '+h+'" preserveAspectRatio="none" style="width:100%;height:'+(h/2.2)+'mm;display:block" shape-rendering="crispEdges" fill="#000">'+r+"</svg>"}
function scaleCode(code,g){var d="21"+("00000"+Math.round(g)).slice(-5)+code;return d+eanChk(d)}
